_UNITS = {
    "m": r"m|meters?|metres?", "mm": r"mm|millimeters?|millimetres?",
    "cm": r"cm|centimeters?|centimetres?", "ft": r"ft|feet|foot",
    "in": r"in|inches?|inch", "relative": r"relative(?:\s+display)?(?:\s+units?)?",
}


def _quantity_number(text):
    try:
