        if word in _WORD_NUMBERS:
            current += _WORD_NUMBERS[word]
        elif word == "hundred":
            current = (current or 1) * 100
        elif word in {"thousand", "million", "billion"}:
            total += (current or 1) * {"thousand": 1000, "million": 1000000, "billion": 1000000000}[word]
            current = 0
        else:
